CREATE TABLE legacy_id_generators (entity_name VARCHAR(255) PRIMARY KEY, next_val BIGINT NOT NULL);
INSERT INTO legacy_id_generators VALUES ('servicios', 1000000), ('checklists', 1000000), ('items_checklist', 1000000), ('logs_auditoria', 1000000), ('usuarios', 1000000);
CREATE TABLE roles (id BIGINT PRIMARY KEY, nombre VARCHAR(255) NOT NULL, descripcion VARCHAR(500), activo BOOLEAN NOT NULL, permisos TEXT);
CREATE TABLE sectores (id BIGINT PRIMARY KEY, nombre VARCHAR(255) NOT NULL);
CREATE TABLE empresas (id BIGINT PRIMARY KEY, nombre VARCHAR(255) NOT NULL);
CREATE TABLE usuarios (id BIGINT PRIMARY KEY, nombre VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, rol_id BIGINT, empresa_id BIGINT);
CREATE TABLE perfiles_organizacionales (id BIGINT AUTO_INCREMENT PRIMARY KEY, empresa_id BIGINT NOT NULL UNIQUE, sector_id BIGINT, tamano VARCHAR(255) NOT NULL, maneja_datos_sensibles BOOLEAN NOT NULL, usa_servicios_nube BOOLEAN NOT NULL, permite_trabajo_remoto BOOLEAN NOT NULL, procesa_pagos BOOLEAN NOT NULL, infraestructura_propia BOOLEAN NOT NULL, depende_proveedores BOOLEAN NOT NULL, servicio_critico_24x7 BOOLEAN NOT NULL, maneja_menores BOOLEAN NOT NULL, opera_ot_iot BOOLEAN NOT NULL, alcance_sgsi VARCHAR(3000), responsable_sgsi VARCHAR(255), umbral_aceptacion INT NOT NULL, actualizado_en TIMESTAMP(6) NOT NULL);
CREATE TABLE servicios (id BIGINT PRIMARY KEY, empresa_id BIGINT NOT NULL, sector_id BIGINT NOT NULL, estado VARCHAR(255) NOT NULL, fecha_creacion TIMESTAMP(6));
CREATE TABLE catalogo_controles (id BIGINT AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(20) NOT NULL UNIQUE, dominio VARCHAR(60) NOT NULL, titulo VARCHAR(60) NOT NULL, descripcion VARCHAR(3000), pregunta_evaluacion VARCHAR(3000), etiquetas VARCHAR(1000), version_norma VARCHAR(50) NOT NULL, activo BOOLEAN NOT NULL);
CREATE TABLE soa_controles (id BIGINT AUTO_INCREMENT PRIMARY KEY, servicio_id BIGINT NOT NULL, control_id BIGINT NOT NULL, aplicabilidad VARCHAR(30) NOT NULL, justificacion_aplicabilidad VARCHAR(3000), estado_implementacion VARCHAR(30) NOT NULL, porcentaje_implementacion INT NOT NULL, responsable VARCHAR(255), fecha_objetivo DATE, observaciones VARCHAR(3000), recomendacion_contextual VARCHAR(1500), puntaje_relevancia INT NOT NULL, creado_en TIMESTAMP(6) NOT NULL, actualizado_en TIMESTAMP(6) NOT NULL, version BIGINT, UNIQUE KEY uq_soa_service_control (servicio_id, control_id));
CREATE TABLE checklists (id BIGINT PRIMARY KEY, nombre VARCHAR(255) NOT NULL, descripcion VARCHAR(1000), estado VARCHAR(255) NOT NULL, servicio_id BIGINT NOT NULL);
CREATE TABLE items_checklist (id BIGINT PRIMARY KEY, pregunta VARCHAR(1000) NOT NULL, respuesta VARCHAR(500), observacion VARCHAR(1000), estado VARCHAR(255) NOT NULL, checklist_id BIGINT NOT NULL);
CREATE TABLE logs_auditoria (id BIGINT PRIMARY KEY, usuario VARCHAR(255) NOT NULL, accion VARCHAR(255) NOT NULL, modulo VARCHAR(255) NOT NULL, descripcion VARCHAR(1000) NOT NULL, fecha TIMESTAMP(6) NOT NULL, ip VARCHAR(255) NOT NULL);
CREATE TABLE evidencias (id BIGINT AUTO_INCREMENT PRIMARY KEY, servicio_id BIGINT NOT NULL, soa_control_id BIGINT NOT NULL, nombre_original VARCHAR(500) NOT NULL, nombre_almacenado VARCHAR(500) NOT NULL, ruta_archivo VARCHAR(1500) NOT NULL, tipo_mime VARCHAR(255), hash_sha256 VARCHAR(64) NOT NULL, descripcion VARCHAR(2000), tipo_evidencia VARCHAR(80), fecha_carga TIMESTAMP(6) NOT NULL, fecha_vencimiento DATE, estado VARCHAR(30) NOT NULL, cargada_por VARCHAR(255) NOT NULL, validada_por VARCHAR(255), fecha_validacion TIMESTAMP(6), observacion_validacion VARCHAR(2000));
CREATE TABLE riesgos (id BIGINT AUTO_INCREMENT PRIMARY KEY, servicio_id BIGINT NOT NULL, codigo VARCHAR(255), nombre VARCHAR(255), descripcion VARCHAR(3000), nivel_inherente VARCHAR(30), estado VARCHAR(30));
CREATE TABLE riesgos_controles (id BIGINT AUTO_INCREMENT PRIMARY KEY, riesgo_id BIGINT NOT NULL, control_id BIGINT NOT NULL, tipo_relacion VARCHAR(40) NOT NULL, eficacia_esperada INT NOT NULL, observacion VARCHAR(1500));
CREATE TABLE hallazgos_auditoria (id BIGINT AUTO_INCREMENT PRIMARY KEY, servicio_id BIGINT NOT NULL, soa_control_id BIGINT, riesgo_id BIGINT, titulo VARCHAR(500) NOT NULL, descripcion VARCHAR(3000) NOT NULL, severidad VARCHAR(30) NOT NULL, estado VARCHAR(30) NOT NULL, recurrente BOOLEAN NOT NULL, fecha_deteccion TIMESTAMP(6) NOT NULL, fecha_cierre TIMESTAMP(6), creado_por VARCHAR(255) NOT NULL);
